import * as Sentry from '@sentry/react';
import { useQuery } from '@tanstack/react-query';
import { useEffect, useRef } from 'react';
import {
  getShopLocationSessionStorage,
  readLastKnownPosition,
  writeLastKnownPosition,
} from '~/entities/shop/model/geolocation-cache';
import type { LastKnownPosition, LocationStorage } from '~/entities/shop/model/geolocation-cache';
import { queries } from '~/shared/api/query-keys';
import { getGlobalQueryClient } from '~/shared/config/query';

export type GeolocationPermissionState = 'granted' | 'denied' | 'prompt' | 'unsupported' | 'unknown';
export type GeolocationFailureReason =
  | 'permission-denied'
  | 'position-unavailable'
  | 'timeout'
  | 'unsupported'
  | 'unknown';

export type GeolocationData =
  | {
      status: 'live';
      permission: 'granted';
      position: LastKnownPosition & { source: 'live' };
      failureReason?: never;
    }
  | {
      status: 'cached';
      permission: GeolocationPermissionState;
      position: LastKnownPosition & { source: 'cached' };
      failureReason: GeolocationFailureReason;
    }
  | {
      status: 'unavailable';
      permission: GeolocationPermissionState;
      position: null;
      failureReason: GeolocationFailureReason;
    };

type PermissionReader = {
  query: (descriptor: PermissionDescriptor) => Promise<{ state: PermissionState }>;
};

type GeolocationReader = Pick<Geolocation, 'getCurrentPosition'>;

export type GeolocationDependencies = {
  geolocation?: GeolocationReader;
  permissions?: PermissionReader;
  storage?: LocationStorage;
  now?: () => number;
};

const recordLocationOutcome = (result: GeolocationData) => {
  Sentry.addBreadcrumb({
    category: 'shop.location',
    message: 'Shop location lookup completed',
    level: result.status === 'unavailable' ? 'warning' : 'info',
    data: {
      status: result.status,
      permission: result.permission,
      failureReason: result.failureReason,
    },
  });
};

const getPermissionState = async (permissions?: PermissionReader): Promise<GeolocationPermissionState> => {
  if (!permissions) return 'unsupported';

  try {
    const result = await permissions.query({ name: 'geolocation' as PermissionName });
    if (result.state === 'granted' || result.state === 'denied' || result.state === 'prompt') {
      return result.state;
    }
  } catch {
    return 'unknown';
  }

  return 'unknown';
};

const getFailureReason = (error: GeolocationPositionError): GeolocationFailureReason => {
  if (error.code === error.PERMISSION_DENIED) return 'permission-denied';
  if (error.code === error.POSITION_UNAVAILABLE) return 'position-unavailable';
  if (error.code === error.TIMEOUT) return 'timeout';
  return 'unknown';
};

const createFallbackResult = (
  permission: GeolocationPermissionState,
  failureReason: GeolocationFailureReason,
  storage?: LocationStorage,
): GeolocationData => {
  const cachedPosition = readLastKnownPosition(storage);
  if (cachedPosition) {
    return {
      status: 'cached',
      permission,
      position: { ...cachedPosition, source: 'cached' },
      failureReason,
    };
  }

  return {
    status: 'unavailable',
    permission,
    position: null,
    failureReason,
  };
};

export const fetchGeolocation = ({
  geolocation = navigator.geolocation,
  permissions = navigator.permissions,
  storage = getShopLocationSessionStorage(),
  now = Date.now,
}: GeolocationDependencies = {}): Promise<GeolocationData> => {
  const permissionStatePromise = getPermissionState(permissions);

  if (!geolocation) {
    return permissionStatePromise.then((permission) => {
      const result = createFallbackResult(permission, 'unsupported', storage);
      recordLocationOutcome(result);
      return result;
    });
  }

  return new Promise<GeolocationData>((resolve) => {
    const resolveFallback = (
      failureReason: GeolocationFailureReason,
      permissionOverride?: GeolocationPermissionState,
    ) => {
      void permissionStatePromise.then((permissionState) => {
        const result = createFallbackResult(permissionOverride ?? permissionState, failureReason, storage);
        recordLocationOutcome(result);
        resolve(result);
      });
    };

    try {
      geolocation.getCurrentPosition(
        (position) => {
          const livePosition: LastKnownPosition = {
            latitude: position.coords.latitude,
            longitude: position.coords.longitude,
            capturedAt: now(),
          };
          writeLastKnownPosition(livePosition, storage);

          const result: GeolocationData = {
            status: 'live',
            permission: 'granted',
            position: { ...livePosition, source: 'live' },
          };
          recordLocationOutcome(result);
          resolve(result);
        },
        (error) => {
          const failureReason = getFailureReason(error);
          resolveFallback(failureReason, failureReason === 'permission-denied' ? 'denied' : undefined);
        },
        {
          enableHighAccuracy: false,
          maximumAge: 0,
          timeout: 3 * 1000,
        },
      );
    } catch {
      resolveFallback('unknown');
    }
  });
};

export const useGeolocationQuery = () => {
  const query = useQuery<GeolocationData>({
    queryKey: queries.location.geolocation.queryKey,
    queryFn: () => fetchGeolocation(),
    meta: { persist: false },
    refetchOnMount: 'always',
    refetchOnWindowFocus: false,
  });
  const refetchRef = useRef(query.refetch);

  useEffect(() => {
    refetchRef.current = query.refetch;
  }, [query.refetch]);

  useEffect(() => {
    let disposed = false;
    let permissionStatus: PermissionStatus | undefined;
    let refetchTimer: ReturnType<typeof setTimeout> | undefined;

    const scheduleRefetch = () => {
      if (disposed || refetchTimer !== undefined) return;
      refetchTimer = setTimeout(() => {
        refetchTimer = undefined;
        void refetchRef.current({ cancelRefetch: false });
      }, 0);
    };

    const handleVisibilityChange = () => {
      if (document.visibilityState === 'visible') scheduleRefetch();
    };

    window.addEventListener('focus', scheduleRefetch);
    document.addEventListener('visibilitychange', handleVisibilityChange);

    if (navigator.permissions?.query) {
      void navigator.permissions
        .query({ name: 'geolocation' as PermissionName })
        .then((status) => {
          if (disposed) return;
          permissionStatus = status;
          permissionStatus.addEventListener('change', scheduleRefetch);
        })
        .catch(() => {
          // Some WebViews expose Permissions API without supporting geolocation queries.
        });
    }

    return () => {
      disposed = true;
      if (refetchTimer !== undefined) clearTimeout(refetchTimer);
      window.removeEventListener('focus', scheduleRefetch);
      document.removeEventListener('visibilitychange', handleVisibilityChange);
      permissionStatus?.removeEventListener('change', scheduleRefetch);
    };
  }, []);

  return query;
};

export const refreshGeolocationQuery = async () => {
  const queryClient = getGlobalQueryClient();
  await queryClient.invalidateQueries({
    queryKey: queries.location.geolocation.queryKey,
    exact: true,
  });
  return queryClient.getQueryData<GeolocationData>(queries.location.geolocation.queryKey);
};
